package com.dormrepair.file.service;
import com.dormrepair.common.enums.*;import com.dormrepair.common.exception.BusinessException;import com.dormrepair.config.*;import com.dormrepair.domain.entity.*;import com.dormrepair.domain.mapper.*;import com.dormrepair.file.vo.*;import com.dormrepair.security.context.UserContext;import io.minio.*;import io.minio.http.Method;import org.slf4j.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.web.multipart.MultipartFile;import java.nio.file.*;import java.time.*;import java.util.*;import java.util.function.*;
@Service public class FileServiceImpl implements FileService {private static final Logger log=LoggerFactory.getLogger(FileServiceImpl.class);private final MinioClient minio;private final com.dormrepair.config.MinioProperties minioProps;private final FileUploadProperties props;private final SysFileMapper files;private final RepairOrderFileMapper orderFiles;private final RepairProcessFileMapper processFiles;private final RepairReworkFileMapper reworkFiles;private final TransactionTemplate transactions;
 public FileServiceImpl(MinioClient m,com.dormrepair.config.MinioProperties mp,FileUploadProperties p,SysFileMapper f,RepairOrderFileMapper of,RepairProcessFileMapper pf,RepairReworkFileMapper rf,TransactionTemplate transactions){minio=m;minioProps=mp;props=p;files=f;orderFiles=of;processFiles=pf;reworkFiles=rf;this.transactions=transactions;}
 @Transactional public FileUploadResponse upload(MultipartFile part,FileBizTypeEnum biz){if(part==null||part.isEmpty())throw new BusinessException(ResultCodeEnum.FILE_EMPTY);var user=UserContext.getCurrentUser();if(!biz.allows(user.getRoleType()))throw new BusinessException(ResultCodeEnum.FORBIDDEN);String original=safeName(part.getOriginalFilename());String suffix=suffix(original);FileTypeEnum type=validate(part,suffix);LocalDate d=LocalDate.now();String object=biz.getPath()+"/"+d.getYear()+"/"+String.format("%02d/%02d/",d.getMonthValue(),d.getDayOfMonth())+UUID.randomUUID().toString().replace("-","")+"."+suffix;boolean uploaded=false;try{minio.putObject(PutObjectArgs.builder().bucket(minioProps.bucketName()).object(object).stream(part.getInputStream(),part.getSize(),-1).contentType(part.getContentType()).build());uploaded=true;SysFile f=new SysFile();f.setOriginalName(original);f.setBucketName(minioProps.bucketName());f.setObjectName(object);f.setFileType(type.name());f.setContentType(part.getContentType());f.setFileSuffix(suffix);f.setFileSize(part.getSize());f.setBizType(biz.name());f.setStatus(1);f.setCreateBy(user.getUserId());f.setDeleted(0);files.insert(f);FileUploadResponse response=new FileUploadResponse(f.getId(),original,type.name(),part.getContentType(),part.getSize(),object,preview(f));log.info("文件上传成功 fileId={} userId={} bizType={} fileType={} size={} objectName={}",f.getId(),user.getUserId(),biz,type,part.getSize(),object);return response;}catch(Exception e){if(uploaded)removeQuietly(minioProps.bucketName(),object);log.error("文件上传失败 bizType={} userId={} objectName={}",biz,user.getUserId(),object,e);throw new BusinessException(ResultCodeEnum.FILE_UPLOAD_FAILED);}}
 @Transactional public void deleteUnusedFile(Long id){SysFile f=files.selectByIdForUpdate(id);if(f==null||Integer.valueOf(1).equals(f.getDeleted()))throw new BusinessException(ResultCodeEnum.FILE_NOT_FOUND);if(!UserContext.getCurrentUserId().equals(f.getCreateBy()))throw new BusinessException(ResultCodeEnum.FILE_NOT_OWNER);deleteLocked(f);}
 public void bindOrderFiles(Long id,List<Long> ids,Long uid){bind(ids,uid,FileBizTypeEnum.REPAIR,(f,n)->{RepairOrderFile r=new RepairOrderFile();r.setRepairOrderId(id);r.setFileId(f.getId());r.setFileType(f.getFileType());r.setSortNo(n);orderFiles.insert(r);});}
 public void bindProcessFiles(Long id,List<Long> ids,Long uid){bind(ids,uid,FileBizTypeEnum.PROCESS,(f,n)->{RepairProcessFile r=new RepairProcessFile();r.setProcessId(id);r.setFileId(f.getId());r.setFileType(f.getFileType());r.setSortNo(n);processFiles.insert(r);});}
 public void bindReworkFiles(Long id,List<Long> ids,Long uid){bind(ids,uid,FileBizTypeEnum.REWORK,(f,n)->{RepairReworkFile r=new RepairReworkFile();r.setReworkId(id);r.setFileId(f.getId());r.setFileType(f.getFileType());r.setSortNo(n);reworkFiles.insert(r);});}
 public List<FileResponse> listOrderFiles(Long id){return map(orderFiles.selectByOrderId(id),RepairOrderFile::getFileId);}public List<FileResponse> listProcessFiles(Long id){return map(processFiles.selectByProcessId(id),RepairProcessFile::getFileId);}public List<FileResponse> listReworkFiles(Long id){return map(reworkFiles.selectByReworkId(id),RepairReworkFile::getFileId);}
 public int cleanupExpiredOrphans(int limit){int done=0;for(Long id:files.selectExpiredCandidateIds(LocalDateTime.now().minus(props.orphanRetention()),Math.min(limit,props.cleanupBatchSize()))){try{Boolean deleted=transactions.execute(status->{SysFile f=files.selectByIdForUpdate(id);if(f==null||bound(id))return false;deleteLocked(f);return true;});if(Boolean.TRUE.equals(deleted))done++;}catch(Exception e){log.warn("孤儿文件清理失败 fileId={}",id,e);}}return done;}
 private void bind(List<Long> ids,Long uid,FileBizTypeEnum biz,BiConsumer<SysFile,Integer> insert){if(ids==null||ids.isEmpty())return;if(ids.stream().anyMatch(Objects::isNull))throw new BusinessException(ResultCodeEnum.PARAM_ERROR,"文件ID不能为空");List<Long> unique=ids.stream().distinct().toList();if(unique.size()>9)throw new BusinessException(ResultCodeEnum.PARAM_ERROR,"文件数量不能超过9个");int n=0;for(Long id:unique){SysFile f=files.selectByIdForUpdate(id);if(f==null||Integer.valueOf(1).equals(f.getDeleted())||!Integer.valueOf(1).equals(f.getStatus()))throw new BusinessException(ResultCodeEnum.FILE_NOT_FOUND);if(!uid.equals(f.getCreateBy()))throw new BusinessException(ResultCodeEnum.FILE_NOT_OWNER);if(!biz.name().equals(f.getBizType()))throw new BusinessException(ResultCodeEnum.FILE_BIZ_TYPE_INVALID);if(bound(id))throw new BusinessException(ResultCodeEnum.FILE_ALREADY_BOUND);insert.accept(f,n++);}}
 private boolean bound(Long id){return orderFiles.existsByFileId(id)>0||processFiles.existsByFileId(id)>0||reworkFiles.existsByFileId(id)>0;}
 private void deleteLocked(SysFile f){if(bound(f.getId()))throw new BusinessException(ResultCodeEnum.FILE_ALREADY_BOUND);try{minio.removeObject(RemoveObjectArgs.builder().bucket(f.getBucketName()).object(f.getObjectName()).build());if(files.markDeleted(f.getId())!=1)throw new BusinessException(ResultCodeEnum.FILE_DELETE_FAILED);}catch(BusinessException e){throw e;}catch(Exception e){log.error("MinIO文件删除失败 fileId={} objectName={}",f.getId(),f.getObjectName(),e);throw new BusinessException(ResultCodeEnum.FILE_DELETE_FAILED);}}
 private <T> List<FileResponse> map(List<T> rows,Function<T,Long> id){if(rows==null)return List.of();return rows.stream().map(r->files.selectById(id.apply(r))).filter(Objects::nonNull).filter(f->Integer.valueOf(0).equals(f.getDeleted())&&Integer.valueOf(1).equals(f.getStatus())).map(f->new FileResponse(f.getId(),f.getOriginalName(),f.getFileType(),f.getContentType(),f.getFileSize(),preview(f))).toList();}
 private String preview(SysFile f){try{return minio.getPresignedObjectUrl(GetPresignedObjectUrlArgs.builder().method(Method.GET).bucket(f.getBucketName()).object(f.getObjectName()).expiry(minioProps.previewExpirySeconds()).build());}catch(Exception e){throw new BusinessException(ResultCodeEnum.FILE_UPLOAD_FAILED,"文件预览地址生成失败");}}
 private FileTypeEnum validate(MultipartFile f,String ext){String mime=Optional.ofNullable(f.getContentType()).orElse("").toLowerCase();if(props.imageExtensions().contains(ext)&&props.imageMimeTypes().contains(mime)){if(f.getSize()>props.imageMaxSize())throw new BusinessException(ResultCodeEnum.FILE_TOO_LARGE);return FileTypeEnum.IMAGE;}if(props.videoExtensions().contains(ext)&&props.videoMimeTypes().contains(mime)){if(f.getSize()>props.videoMaxSize())throw new BusinessException(ResultCodeEnum.FILE_TOO_LARGE);return FileTypeEnum.VIDEO;}throw new BusinessException(ResultCodeEnum.FILE_TYPE_NOT_ALLOWED);}
 private String safeName(String name){if(name==null||name.isBlank())throw new BusinessException(ResultCodeEnum.FILE_TYPE_NOT_ALLOWED);return Paths.get(name.replace('\\','/')).getFileName().toString();}private String suffix(String n){int i=n.lastIndexOf('.');if(i<1||i==n.length()-1)throw new BusinessException(ResultCodeEnum.FILE_TYPE_NOT_ALLOWED);return n.substring(i+1).toLowerCase();}private void removeQuietly(String b,String o){try{minio.removeObject(RemoveObjectArgs.builder().bucket(b).object(o).build());}catch(Exception e){log.error("上传补偿删除失败 objectName={}",o,e);}}
}
